// Gerado a partir do material de formação. Não editar à mão.
import type { CapituloDoLivro } from "./tipos";

export const capitulos: CapituloDoLivro[] = [{"id":"c1","titulo":"A escola e o seu território","html":"<p>A escola faz parte de um bairro, com suas relações, seus conflitos e, em alguns lugares, com a presença de grupos armados. Esses fatores entram na rotina da escola mesmo quando ninguém fala sobre eles.</p><p>Este guia trata de três frentes: os conflitos com famílias, a relação com a comunidade e a conduta diante da violência armada no entorno. Em todas, vale a mesma regra: a vida e a proteção das pessoas vêm antes de qualquer outra decisão.</p><h3>Ao final, você será capaz de</h3><ul><li>Conduzir uma conversa difícil com um responsável.</li><li>Acionar a rede de proteção no caso certo e pelo caminho certo.</li><li>Preparar a escola para uma situação de violência no entorno.</li><li>Agir com segurança durante e depois de uma crise.</li><li>Apoiar alunos afetados sem expor nem rotular.</li><li>Cuidar da equipe.</li></ul><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>O que significa</th></tr></thead><tbody><tr><td>Proteção da vida</td><td>Nenhuma atividade, prova ou meta vale o risco à vida de alunos e servidores.</td></tr><tr><td>Neutralidade</td><td>A escola atende a todos e não toma partido em disputas do território.</td></tr><tr><td>Papel da escola</td><td>A escola educa e protege. Não investiga, não julga e não substitui a polícia nem a assistência social.</td></tr><tr><td>Sigilo</td><td>Informações sobre alunos e famílias são tratadas com reserva.</td></tr><tr><td>Trabalho em rede</td><td>Nenhuma escola resolve sozinha. A direção aciona a Secretaria e os serviços de proteção.</td></tr></tbody></table></div>"},{"id":"c2","titulo":"Conflitos com famílias","html":"<p>A maior parte dos conflitos com responsáveis nasce de falta de informação, de uma decisão não explicada ou de uma preocupação que não foi ouvida.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Acolher</b><small>receber em local reservado</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Ouvir</b><small>sem interromper nem se defender</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Entender</b><small>resumir o que foi dito</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Combinar</b><small>o que a escola fará e em que prazo</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Dar retorno</b><small>na data combinada</small></div></div><figcaption>Figura. Os passos de uma conversa difícil com um responsável.</figcaption></figure><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Como conduzir</th></tr></thead><tbody><tr><td>Responsável chega exaltado</td><td>Levar a um local reservado, com duas pessoas da escola. Falar baixo e devagar. Não discutir no portão nem diante de alunos.</td></tr><tr><td>Queixa sobre um professor</td><td>Ouvir, registrar os fatos e dizer que a escola vai ouvir o professor. Não dar razão a nenhum dos lados antes disso.</td></tr><tr><td>Briga entre alunos envolve as famílias</td><td>Atender cada família em separado. Tratar dos fatos e do que a escola fará, sem comparar os alunos.</td></tr><tr><td>Responsável ameaça um servidor</td><td>Encerrar o atendimento, registrar o ocorrido, comunicar à Secretaria e, havendo risco, acionar a polícia.</td></tr><tr><td>Família não comparece</td><td>Tentar outros horários e meios. Persistindo a ausência com prejuízo ao aluno, comunicar ao Conselho Tutelar.</td></tr></tbody></table></div><div class=\"nota\"><b>Registro</b><br/>Todo atendimento de conflito é registrado no mesmo dia: data, quem participou, o que foi relatado e o que foi combinado. O registro protege o aluno, a família e o servidor.</div>"},{"id":"c3","titulo":"Mediação de conflitos na escola","html":"<p>Em conflitos entre alunos, ou entre aluno e professor, a mediação busca reparar a relação e evitar que o problema volte. Ela não substitui as providências previstas no regimento quando há violência.</p><ol class=\"passos\"><li>Ouça cada parte em separado.</li><li>Verifique se as duas aceitam conversar.</li><li>Reúna as partes, com regras claras: um fala por vez, sem ofensas.</li><li>Peça que cada um diga o que aconteceu e como se sentiu.</li><li>Construa um combinado concreto, com o que cada um fará.</li><li>Acompanhe nos dias seguintes.</li></ol><div class=\"nota alerta\"><b>Quando não mediar</b><br/>Não se faz mediação em casos de violência sexual, ameaça grave, agressão com lesão ou quando uma das partes tem medo da outra. Nesses casos, a escola protege a vítima e aciona a rede de proteção.</div>"},{"id":"c4","titulo":"A rede de proteção","html":"<p>A escola é uma das portas da rede de proteção da criança e do adolescente. Conhecer os serviços e ter os contatos à mão antes de precisar é parte do trabalho da gestão.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Serviço</th><th>Quando acionar</th><th>Como</th></tr></thead><tbody><tr><td>Conselho Tutelar</td><td>Suspeita ou confirmação de violência, negligência ou violação de direitos de criança ou adolescente.</td><td>Comunicação pela direção da escola. É obrigatória.</td></tr><tr><td>Disque 100</td><td>Denúncia de violação de direitos humanos, inclusive anônima.</td><td>Telefone 100, todos os dias, 24 horas.</td></tr><tr><td>Polícia Militar</td><td>Risco imediato à vida ou crime em andamento.</td><td>Telefone 190.</td></tr><tr><td>SAMU</td><td>Pessoa ferida ou em emergência de saúde.</td><td>Telefone 192.</td></tr><tr><td>CRAS e CREAS</td><td>Família em vulnerabilidade ou com direitos violados.</td><td>Encaminhamento pela direção ou pelo Conselho Tutelar.</td></tr><tr><td>Unidade de saúde e CAPS</td><td>Sofrimento emocional, uso de substâncias ou suspeita de transtorno.</td><td>Encaminhamento pela escola, com a família.</td></tr><tr><td>Ministério Público e Defensoria Pública</td><td>Violação de direitos sem resposta dos demais serviços.</td><td>Pela Secretaria de Educação ou pela direção.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>Comunicação obrigatória</b><br/>O Estatuto da Criança e do Adolescente obriga a comunicar ao Conselho Tutelar os casos de suspeita ou confirmação de maus-tratos (art. 13). Deixar de comunicar é infração para o professor e para o responsável pela escola (art. 245). A escola comunica a suspeita. Não precisa provar.</div>"},{"id":"c5","titulo":"Quando o território afeta a rotina da escola","html":"<p>Em áreas com presença de grupos armados, a escola pode enfrentar disparos no entorno, toques de recolher, ameaças e pressão sobre alunos e famílias. A gestão não controla esses fatores, mas pode preparar a escola para reduzir os riscos.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Sinal no território</th><th>O que observar</th><th>O que fazer</th></tr></thead><tbody><tr><td>Movimentação incomum</td><td>Comércio fechando, ruas vazias, alunos sendo buscados mais cedo.</td><td>Confirmar com parceiros do território e avisar a Secretaria.</td></tr><tr><td>Queda brusca de frequência</td><td>Muitas faltas em um mesmo dia ou de uma mesma região.</td><td>Procurar entender o motivo antes de cobrar presença.</td></tr><tr><td>Pressão sobre a escola</td><td>Pedidos para fechar, mudar horário ou liberar o espaço.</td><td>Não negociar sozinho. Comunicar imediatamente à Secretaria.</td></tr><tr><td>Alunos com medo de ir ou de voltar</td><td>Relatos de trajeto perigoso.</td><td>Registrar e levar à Secretaria e ao Conselho Tutelar.</td></tr></tbody></table></div><div class=\"nota alerta\"><b>O que a escola não faz</b><br/>A escola não confronta, não investiga, não repassa informações sobre pessoas do território e não faz acordos. Qualquer contato de grupos armados com a escola é comunicado à Secretaria no mesmo dia.</div>"},{"id":"c6","titulo":"Como preparar a escola","html":"<p>A preparação segue os eixos da metodologia Acesso Mais Seguro, do Comitê Internacional da Cruz Vermelha, usada por redes públicas no Brasil: conhecer o contexto, tratar os riscos, gerir a crise e cuidar da equipe.</p><figure><div class=\"ciclo\"><div class=\"q\"><span class=\"n\">1</span><b>Conhecer</b><small>Mapear os riscos do entorno e os horários mais sensíveis.</small></div><div class=\"q\"><span class=\"n\">2</span><b>Preparar</b><small>Definir locais mais seguros, rotas, sinais de alerta e quem decide.</small></div><div class=\"q\"><span class=\"n\">3</span><b>Agir</b><small>Seguir o combinado durante a crise.</small></div><div class=\"q\"><span class=\"n\">4</span><b>Cuidar</b><small>Acolher alunos e equipe e rever o plano.</small></div><div class=\"volta\">volta ao passo 1 na semana seguinte</div></div><figcaption>Figura. O ciclo de preparação da escola.</figcaption></figure><ul class=\"chk\"><li><span></span>A escola definiu o local mais seguro de cada bloco, longe de janelas e de paredes voltadas para a rua.</li><li><span></span>Todos os servidores conhecem o sinal combinado e sabem o que fazer com a turma.</li><li><span></span>Há uma pessoa responsável por decidir e uma substituta, em cada turno.</li><li><span></span>A lista de telefones da Secretaria, da rede de proteção e dos responsáveis está atualizada e impressa.</li><li><span></span>A escola combinou com a Secretaria quem decide sobre suspensão de aulas e liberação de alunos.</li><li><span></span>Os responsáveis foram informados de como a escola age e de que os alunos não são liberados durante o risco.</li><li><span></span>Novos servidores recebem a orientação ao chegar.</li></ul>"},{"id":"c7","titulo":"Durante e depois de uma crise","html":"<div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Momento</th><th>O que fazer</th><th>O que evitar</th></tr></thead><tbody><tr><td>Antes</td><td>Conhecer o território e os sinais de alerta. Definir o local mais seguro da escola, as rotas e os pontos de encontro. Manter a lista de telefones atualizada.</td><td>Rotas perigosas, mesmo que mais curtas. Deslocar-se sozinho em área de risco.</td></tr><tr><td>Durante disparos</td><td>Deitar-se e orientar os alunos a deitar. Afastar todos de janelas e portas. Levar o grupo, abaixado, ao local mais seguro e permanecer lá.</td><td>Olhar pela janela. Filmar ou fotografar. Usar o telefone antes de estar protegido. Liberar os alunos.</td></tr><tr><td>Depois</td><td>Esperar algum tempo, pois pode haver novos disparos. Confirmar com parceiros do território que a situação normalizou. Avisar a equipe e a Secretaria.</td><td>Sair logo após os disparos. Tocar em armas ou munições. Compartilhar imagens.</td></tr></tbody></table></div><h3>Decisões da direção</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Decisão</th><th>Critério</th></tr></thead><tbody><tr><td>Manter os alunos na escola</td><td>Enquanto houver risco no entorno, a escola é mais segura do que a rua.</td></tr><tr><td>Liberar os alunos</td><td>Somente após confirmar que a situação normalizou e, se possível, com entrega aos responsáveis.</td></tr><tr><td>Suspender as aulas</td><td>Decisão tomada com a Secretaria, com base nas informações do território.</td></tr><tr><td>Comunicar os responsáveis</td><td>Mensagem curta, pelos canais da escola: os alunos estão protegidos, não venham buscar agora, a escola avisará.</td></tr></tbody></table></div><h3>Depois</h3><ul><li>Verifique se há feridos e acione o SAMU.</li><li>Reúna a equipe, ainda no mesmo dia, para ouvir e orientar.</li><li>Registre o ocorrido e comunique à Secretaria.</li><li>No retorno às aulas, reserve tempo para os alunos falarem, sem obrigar ninguém.</li><li>Reveja o plano: o que funcionou e o que precisa mudar.</li></ul>"},{"id":"c8","titulo":"Alunos e famílias afetados","html":"<div class=\"tb\"><table class=\"larga\"><thead><tr><th>Situação</th><th>Conduta da gestão</th></tr></thead><tbody><tr><td>Aluno com familiar preso, morto ou envolvido com grupos armados</td><td>Acolher sem perguntar detalhes. Garantir que não seja rotulado. Acionar o apoio psicossocial da rede.</td></tr><tr><td>Aluno que perdeu colega ou parente pela violência</td><td>Avisar os professores com discrição. Flexibilizar prazos. Encaminhar à unidade de saúde.</td></tr><tr><td>Família ameaçada ou que precisa sair do bairro</td><td>Facilitar a transferência com sigilo. Não divulgar o destino.</td></tr><tr><td>Suspeita de que um aluno está sendo aliciado</td><td>Não confrontar o aluno nem terceiros. Comunicar ao Conselho Tutelar e à Secretaria. Reforçar o vínculo com a escola.</td></tr><tr><td>Aluno que traz arma ou objeto ilícito</td><td>Não revistar nem enfrentar. Afastar os demais, manter a calma e seguir o protocolo da Secretaria.</td></tr></tbody></table></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a turma que parou de vir</div><p><b>Situação.</b> Em uma semana, metade dos alunos de uma região do bairro falta todos os dias. Ninguém explica o motivo.</p><p><b>O que fazer.</b></p><ol><li>Converse com responsáveis de confiança, em separado, para entender o que ocorre.</li><li>Não cobre presença nem registre a falta como desinteresse.</li><li>Comunique à Secretaria e, se houver risco no trajeto, ao Conselho Tutelar.</li><li>Ofereça atividades para casa e o reforço escolar enquanto durar a situação.</li><li>Quando os alunos voltarem, acolha sem interrogar.</li></ol><p><b>Resultado esperado.</b> Os alunos mantêm o vínculo com a escola, e a rede de proteção passa a acompanhar o caso.</p></div>"},{"id":"c9","titulo":"Cuidado com a equipe","html":"<p>Trabalhar sob tensão constante adoece. O quarto eixo do Acesso Mais Seguro é a gestão do estresse, e ele depende da gestão da escola.</p><ul><li>Depois de uma crise, reúna a equipe para falar do que viveu. Ouvir já ajuda.</li><li>Observe sinais de esgotamento: faltas, irritação, isolamento, choro.</li><li>Encaminhe quem precisa ao serviço de saúde do servidor.</li><li>Não exija que ninguém permaneça em situação de risco.</li><li>Reconheça o trabalho da equipe.</li></ul><div class=\"nota\"><b>Apoio emocional</b><br/>O Centro de Valorização da Vida atende pelo telefone 188, todos os dias, 24 horas, sem custo de ligação.</div>"},{"id":"c10","titulo":"Conhecer o território da escola","html":"<p>Preparar a escola começa por conhecer o lugar onde ela está. Esse conhecimento é construído pela equipe, com quem vive e trabalha no bairro, e é revisto todo semestre.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>O que mapear</th><th>Perguntas</th><th>Fontes</th></tr></thead><tbody><tr><td>De onde vêm os alunos</td><td>De que ruas e localidades? Por quais caminhos? A pé ou de transporte?</td><td>Cadastro, professores, transporte escolar.</td></tr><tr><td>Pontos sensíveis</td><td>Que trechos e horários concentram ocorrências?</td><td>Servidores que moram no bairro, agentes de saúde.</td></tr><tr><td>Sinais de alerta</td><td>O que muda no bairro antes de um episódio?</td><td>Comerciantes, porteiros, responsáveis.</td></tr><tr><td>Serviços e parceiros</td><td>Quem atua no entorno e pode confirmar informações?</td><td>Unidade de saúde, CRAS, associações, igrejas.</td></tr><tr><td>Estrutura da escola</td><td>Que salas ficam voltadas para a rua? Onde é mais protegido?</td><td>Vistoria com a equipe.</td></tr><tr><td>Histórico</td><td>O que já aconteceu, quando e como a escola agiu?</td><td>Registros e memória da equipe.</td></tr></tbody></table></div><h3>A rede de parceiros do território</h3><p>Parceiros são pessoas e serviços que trabalham no bairro e podem dizer, com rapidez, se a situação está normal. A escola combina com eles um modo simples de troca de avisos.</p><ul class=\"chk\"><li><span></span>Unidade básica de saúde e agentes comunitários.</li><li><span></span>CRAS e demais serviços de assistência.</li><li><span></span>Outras escolas e creches do entorno.</li><li><span></span>Transporte escolar.</li><li><span></span>Associação de moradores e lideranças reconhecidas.</li><li><span></span>Comércio vizinho.</li></ul><div class=\"nota alerta\"><b>O mapa é reservado</b><br/>As informações sobre o território ficam com a direção. Não são afixadas, não circulam em grupos e não citam nomes de pessoas.</div><div class=\"pratica\"><div class=\"tt\">Para praticar · o território da sua escola</div><div class=\"q\"><b>1.</b> Quais são os três caminhos mais usados pelos alunos?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>2.</b> Quem são dois parceiros que podem confirmar uma informação em poucos minutos?<div class=\"ln\"></div><div class=\"ln\"></div></div><div class=\"q\"><b>3.</b> Qual é o local mais protegido de cada bloco da escola?<div class=\"ln\"></div><div class=\"ln\"></div></div></div>"},{"id":"c11","titulo":"Avaliar o risco e definir níveis de alerta","html":"<p>Nem toda situação pede a mesma resposta. Definir níveis de alerta, com ações combinadas para cada um, evita tanto o pânico quanto a demora.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Nível</th><th>Situação</th><th>O que a escola faz</th></tr></thead><tbody><tr><td>Normal</td><td>Sem sinais de alteração no entorno.</td><td>Rotina. Plano revisado, equipe orientada, contatos atualizados.</td></tr><tr><td>Atenção</td><td>Sinais de tensão: boatos, movimentação incomum, ocorrência recente por perto.</td><td>Direção confirma com parceiros e avisa a Secretaria. Atividades externas suspensas. Portões e fluxo de visitantes controlados.</td></tr><tr><td>Alerta</td><td>Ocorrência em andamento no entorno, sem atingir a escola.</td><td>Alunos permanecem dentro dos prédios, longe de áreas expostas. Ninguém é liberado. Responsáveis são informados pelo canal oficial.</td></tr><tr><td>Emergência</td><td>Disparos próximos ou risco direto à escola.</td><td>Sinal combinado. Todos nos locais mais seguros, deitados ou abaixados. Acionamento do 190 e da Secretaria.</td></tr></tbody></table></div><figure><div class=\"matriz\"><div class=\"ey\">Gravidade</div><div class=\"grade\"><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Grave e pouco provável</b><small>Ter plano e treinar.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #C44536\"><b>Grave e provável</b><small>Prioridade máxima: medidas imediatas com a Secretaria.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #1E8E5A\"><b>Leve e pouco provável</b><small>Acompanhar.</small></div><div class=\"q\" style=\"border-top:1.2mm solid #D9920B\"><b>Leve e provável</b><small>Ajustar rotinas.</small></div></div><div class=\"ex\">Probabilidade</div></div><figcaption>Figura. Como ordenar os riscos identificados.</figcaption></figure><h3>Quem decide</h3><ul><li>Em cada turno há uma pessoa que decide e uma substituta.</li><li>A mudança de nível é comunicada a toda a equipe por um sinal conhecido.</li><li>A suspensão de aulas é decidida com a Secretaria.</li><li>Toda decisão é registrada com data e hora.</li></ul>"},{"id":"c12","titulo":"O plano de segurança da escola","html":"<p>O plano é um documento curto, de duas ou três páginas, que qualquer servidor consegue ler em cinco minutos. Ele é construído com a equipe e aprovado pela Secretaria.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Parte</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Responsáveis</td><td>Quem decide em cada turno, quem substitui e quem fala com a Secretaria e com os responsáveis.</td></tr><tr><td>Níveis de alerta</td><td>O que caracteriza cada nível e o que fazer.</td></tr><tr><td>Sinais</td><td>Como a equipe é avisada: sinal sonoro, mensagem, aviso de sala em sala.</td></tr><tr><td>Locais mais seguros</td><td>Para cada bloco e turma, onde ficar e por onde ir.</td></tr><tr><td>Pessoas que precisam de apoio</td><td>Alunos com deficiência, crianças menores, quem está fora da sala.</td></tr><tr><td>Entrada e saída</td><td>Como os alunos chegam, saem e são entregues aos responsáveis em dias de risco.</td></tr><tr><td>Comunicação</td><td>Lista de telefones, canal oficial com as famílias e mensagens-modelo.</td></tr><tr><td>Depois da crise</td><td>Verificação, acolhimento, registro e retomada.</td></tr><tr><td>Formação e revisão</td><td>Quando a equipe treina e quando o plano é revisto.</td></tr></tbody></table></div><h3>Como escolher o local mais seguro</h3><ul><li>Longe de janelas, portas de vidro e paredes voltadas para a rua.</li><li>De preferência no térreo e no interior do prédio, como corredores internos.</li><li>Com paredes de alvenaria entre as pessoas e a rua.</li><li>Com espaço para todos ficarem deitados ou sentados no chão.</li><li>Conhecido por todos e sinalizado de forma discreta.</li></ul><h3>Treinar sem assustar</h3><ol class=\"passos\"><li>Explique aos alunos, com calma, que a escola tem um combinado para manter todos seguros, como tem para incêndio.</li><li>Ensine o procedimento em sala: ao sinal, abaixar, afastar-se das janelas, seguir o professor.</li><li>Faça o percurso até o local mais seguro, sem pressa.</li><li>Não use sons de disparos nem simule cenas de violência.</li><li>Converse depois: o que funcionou, quem ficou com medo, o que mudar.</li><li>Repita a cada semestre e sempre que chegarem alunos novos.</li></ol><div class=\"nota\"><b>Informar os responsáveis</b><br/>No início do ano, a escola explica às famílias como age em situações de risco e por que os alunos não são liberados durante uma ocorrência. Famílias informadas confiam mais e correm menos para a porta da escola.</div>"},{"id":"c13","titulo":"Comunicação durante a crise","html":"<p>Na crise, a falta de informação gera boatos, e os boatos levam os responsáveis a se deslocarem para a escola no pior momento. Mensagens curtas, verdadeiras e frequentes protegem.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Para quem</th><th>O que comunicar</th><th>Por onde</th><th>Quem</th></tr></thead><tbody><tr><td>Equipe</td><td>Nível de alerta e o que fazer.</td><td>Sinal combinado e grupo de servidores.</td><td>Direção</td></tr><tr><td>Secretaria</td><td>O que ocorre, desde quando, medidas tomadas e do que a escola precisa.</td><td>Telefone direto.</td><td>Direção</td></tr><tr><td>Segurança pública e SAMU</td><td>Local, o que ocorre, se há feridos.</td><td>190 e 192.</td><td>Direção ou substituto</td></tr><tr><td>Responsáveis</td><td>Os alunos estão protegidos. Não venham agora. A escola avisará.</td><td>Canal oficial.</td><td>Pessoa designada</td></tr><tr><td>Imprensa</td><td>Encaminhar à Secretaria.</td><td></td><td>Secretaria</td></tr></tbody></table></div><h3>Mensagens-modelo para os responsáveis</h3><div class=\"rapido\"><p><b>Durante:</b> \"Senhores responsáveis: há uma ocorrência nas proximidades da escola. Todos os alunos estão dentro do prédio, protegidos e acompanhados. Por segurança, pedimos que não venham à escola agora. Daremos nova informação em breve. Direção.\"</p><p><b>Liberação:</b> \"Senhores responsáveis: a situação no entorno foi normalizada. A saída dos alunos será feita a partir das ____ horas, pelo portão ____. Os alunos menores serão entregues somente aos responsáveis. Direção.\"</p><p><b>Suspensão de aulas:</b> \"Senhores responsáveis: por orientação da Secretaria Municipal de Educação, não haverá aula amanhã, dia ____. Informaremos o retorno por este canal. Direção.\"</p><p><b>Retorno:</b> \"Senhores responsáveis: as aulas serão retomadas amanhã, dia ____, no horário normal. A equipe estará preparada para acolher os alunos. Direção.\"</p></div><h3>Cuidados</h3><ul><li>Não informar detalhes da ocorrência, apenas o que afeta os alunos.</li><li>Não citar pessoas, grupos ou locais além do necessário.</li><li>Repetir a informação em intervalos regulares, mesmo sem novidade.</li><li>Não responder a boatos um a um. Reafirmar o canal oficial.</li><li>Guardar cópia das mensagens enviadas.</li></ul>"},{"id":"c14","titulo":"Suspender, retomar e repor aulas","html":"<p>Fechar a escola protege em um dia de risco, mas cada dia sem aula também tem custo: os alunos perdem conteúdo, alimentação e proteção. A decisão é tomada com a Secretaria, com base em informação confirmada.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Decisão provável</th><th>Observações</th></tr></thead><tbody><tr><td>Risco confirmado antes do início do turno</td><td>Não abrir o turno.</td><td>Avisar os responsáveis e o transporte escolar o mais cedo possível.</td></tr><tr><td>Risco surge com os alunos na escola</td><td>Manter todos na escola até a normalização.</td><td>Não liberar durante a ocorrência.</td></tr><tr><td>Risco na hora da saída</td><td>Adiar a saída.</td><td>Entrega aos responsáveis. Combinar com o transporte.</td></tr><tr><td>Tensão que se prolonga por dias</td><td>Avaliação diária com a Secretaria.</td><td>Considerar horário reduzido e atividades para casa.</td></tr><tr><td>Boato não confirmado</td><td>Manter as aulas e informar os responsáveis.</td><td>Registrar a origem do boato.</td></tr></tbody></table></div><h3>O primeiro dia de volta</h3><ol class=\"passos\"><li>A equipe se reúne antes da entrada dos alunos.</li><li>Os alunos são recebidos no portão pelos adultos da escola.</li><li>A primeira aula reserva tempo para quem quiser falar, sem obrigar ninguém.</li><li>A rotina é retomada com atividades mais leves.</li><li>Os professores observam quem está muito abalado e avisam a coordenação.</li><li>A alimentação escolar é garantida.</li></ol><h3>Reposição e aprendizagem</h3><ul><li>O calendário letivo é recomposto conforme as orientações da Secretaria, para garantir os dias e as horas previstos em lei.</li><li>A frequência é acompanhada: alunos que não voltam entram na busca ativa.</li><li>O reforço escolar ajuda a recuperar os conteúdos, e o aluno pode estudar em casa quando há equipamento e conexão.</li><li>Provas e prazos são reorganizados sem prejuízo para os alunos.</li></ul><div class=\"nota\"><b>Faltas em dias de risco</b><br/>A ausência de alunos em dias de ocorrência no bairro é tratada com compreensão. A escola procura a família para saber como estão, e não para cobrar.</div>"},{"id":"c15","titulo":"Pressões sobre a escola","html":"<p>Em alguns territórios, a escola recebe pedidos e recados que não vêm da Secretaria: fechar em determinado dia, liberar o espaço, mudar um horário, matricular ou transferir alguém. Nenhum gestor deve lidar com isso sozinho.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td>Recado para fechar a escola</td><td>Não discutir com o portador. Comunicar imediatamente à Secretaria, que decide com os órgãos competentes.</td></tr><tr><td>Pedido de uso do prédio ou da quadra</td><td>Informar que o uso depende de autorização da Secretaria. Registrar e comunicar.</td></tr><tr><td>Oferta de doação, festa ou reforma</td><td>Agradecer, informar que a escola só recebe doações pelos meios oficiais e comunicar.</td></tr><tr><td>Pressão para favorecer ou prejudicar um aluno</td><td>Aplicar as regras da rede, iguais para todos. Comunicar.</td></tr><tr><td>Pedido de informação sobre aluno, família ou servidor</td><td>Não fornecer. Dados são protegidos por lei.</td></tr><tr><td>Presença de pessoas armadas nas proximidades</td><td>Recolher os alunos para dentro, sem alarde, e seguir o nível de alerta.</td></tr><tr><td>Ameaça a um servidor</td><td>Proteger o servidor, comunicar à Secretaria no mesmo momento e registrar ocorrência.</td></tr></tbody></table></div><h3>Como se portar em um contato</h3><ul><li>Manter a calma, o tom respeitoso e frases curtas.</li><li>Não prometer, não negociar e não confrontar.</li><li>Dizer que decisões sobre a escola são da Secretaria.</li><li>Não ficar sozinho: ter outro servidor por perto.</li><li>Encerrar o contato assim que possível.</li><li>Registrar por escrito, logo depois, o que foi dito, sem identificar pessoas além do necessário.</li></ul><div class=\"nota alerta\"><b>Não é decisão da escola</b><br/>Acordos locais colocam o gestor em risco e comprometem a neutralidade da escola. Todo contato desse tipo é levado à Secretaria no mesmo dia, pelo canal reservado.</div>"},{"id":"c16","titulo":"Relação com as forças de segurança","html":"<p>A escola colabora com as autoridades dentro da lei e do seu papel. Ela não é fonte de informação sobre moradores, e os servidores não atuam como intermediários.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Conduta da direção</th></tr></thead><tbody><tr><td>Ronda escolar e ações preventivas</td><td>Receber, combinar horários e manter o contato institucional pela Secretaria.</td></tr><tr><td>Operação policial no entorno</td><td>Seguir o nível de alerta. Manter os alunos protegidos. Informar a Secretaria.</td></tr><tr><td>Pedido de entrada na escola durante operação</td><td>Atender à autoridade, proteger os alunos e comunicar à Secretaria imediatamente.</td></tr><tr><td>Pedido de informações ou de documentos de alunos</td><td>Solicitar o pedido formal, por escrito, e encaminhar à Secretaria.</td></tr><tr><td>Ouvir um aluno na escola</td><td>A escola não realiza nem permite interrogatórios. Chamar os responsáveis e o Conselho Tutelar.</td></tr><tr><td>Crime dentro da escola</td><td>Proteger as pessoas, preservar o local, acionar o 190 e a Secretaria.</td></tr></tbody></table></div><h3>Substâncias e armas na escola</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>O que fazer</th><th>O que não fazer</th></tr></thead><tbody><tr><td>Aluno com sinais de uso de substância</td><td>Acolher, cuidar da saúde, chamar os responsáveis, encaminhar à rede de saúde.</td><td>Expor, humilhar ou revistar diante de colegas.</td></tr><tr><td>Substância encontrada com aluno</td><td>Recolher com testemunha, guardar em local seguro, chamar os responsáveis e seguir a orientação da Secretaria.</td><td>Devolver, descartar por conta própria ou divulgar.</td></tr><tr><td>Suspeita de venda na escola</td><td>Comunicar à Secretaria e ao Conselho Tutelar. Tratar o adolescente como pessoa em situação de exploração.</td><td>Investigar, montar flagrante ou confrontar.</td></tr><tr><td>Arma ou objeto perigoso com aluno</td><td>Manter a calma, afastar os demais, pedir que o objeto seja deixado em local indicado, acionar o 190.</td><td>Tentar tomar à força.</td></tr><tr><td>Arma ou munição encontrada</td><td>Isolar o local, não tocar, acionar o 190.</td><td>Manusear, guardar ou fotografar para grupos.</td></tr></tbody></table></div><div class=\"nota\"><b>Revista de alunos</b><br/>Servidores da escola não fazem revista pessoal. Diante de suspeita fundada de risco, a direção isola a situação e aciona a autoridade competente e os responsáveis.</div>"},{"id":"c17","titulo":"Como a violência afeta a aprendizagem","html":"<p>Crianças e adolescentes que convivem com tiroteios, ameaças, perdas e medo constante vivem em estado de alerta. O corpo se prepara o tempo todo para o perigo, e sobra pouca energia para prestar atenção, memorizar e controlar impulsos.</p><p>Muitos comportamentos que a escola lê como desinteresse ou indisciplina são, nesses casos, respostas de quem aprendeu a se proteger.</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>O que a escola vê</th><th>O que pode estar acontecendo</th></tr></thead><tbody><tr><td>Sono em sala</td><td>Noites sem dormir por medo, barulho ou vigília.</td></tr><tr><td>Sustos e reações exageradas a ruídos</td><td>Estado de alerta permanente.</td></tr><tr><td>Explosões de raiva por motivos pequenos</td><td>Dificuldade de regular emoções sob tensão.</td></tr><tr><td>\"Desligamento\", olhar distante</td><td>Forma de se afastar de lembranças e do medo.</td></tr><tr><td>Esquecimento do que foi ensinado ontem</td><td>A tensão prejudica a memória.</td></tr><tr><td>Desconfiança de adultos</td><td>Experiências em que adultos não protegeram.</td></tr><tr><td>Faltas em determinados dias</td><td>Trajeto inseguro, operações, luto na família.</td></tr><tr><td>Brincadeiras e desenhos com armas e mortes</td><td>Tentativa de dar sentido ao que viu.</td></tr></tbody></table></div><h3>O que ajuda: quatro pilares</h3><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Pilar</th><th>Na prática</th></tr></thead><tbody><tr><td>Segurança</td><td>O aluno sabe que na escola nenhum adulto vai gritar, humilhar ou agredir.</td></tr><tr><td>Previsibilidade</td><td>Rotina conhecida, avisos antes de mudanças, combinados estáveis.</td></tr><tr><td>Vínculo</td><td>Pelo menos um adulto que sabe o nome dele, nota quando falta e pergunta como está.</td></tr><tr><td>Escolha</td><td>Pequenas decisões ao alcance dele: onde sentar, por qual atividade começar.</td></tr></tbody></table></div><div class=\"nota\"><b>Entender não é desculpar</b><br/>Compreender a origem do comportamento não significa abrir mão das regras. Significa aplicá-las com calma, sem humilhação, e ensinar o que o aluno ainda não sabe fazer.</div>"},{"id":"c18","titulo":"Luto na escola","html":"<p>A morte de um familiar, de um colega ou de alguém do bairro chega à escola no dia seguinte. A escola não precisa ter respostas. Precisa reconhecer a perda, acolher e manter a rotina.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Idade</th><th>Como costuma reagir</th><th>O que ajuda</th></tr></thead><tbody><tr><td>6 a 8 anos</td><td>Faz perguntas diretas e repetidas. Alterna tristeza e brincadeira. Pode achar que causou a morte.</td><td>Respostas simples e verdadeiras. Dizer que não foi culpa dela. Desenho e brincadeira.</td></tr><tr><td>9 a 11 anos</td><td>Entende que a morte é definitiva. Sente medo de perder outras pessoas. Pode ter dores sem causa médica.</td><td>Espaço para falar. Rotina. Atenção a faltas e queda no rendimento.</td></tr><tr><td>12 a 14 anos</td><td>Esconde o que sente. Pode reagir com raiva, isolamento ou comportamento de risco. Em mortes violentas, pode falar em vingança.</td><td>Conversa em particular, sem pressa. Um adulto de referência. Encaminhamento quando há ideias de revide ou de autolesão.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Dizer</th><th>Evitar</th></tr></thead><tbody><tr><td>\"Sinto muito pelo que aconteceu.\"</td><td>\"Eu sei como você se sente.\"</td></tr><tr><td>\"Estou aqui se você quiser conversar.\"</td><td>\"Você precisa ser forte.\"</td></tr><tr><td>\"Tudo bem chorar.\"</td><td>\"Não chore.\"</td></tr><tr><td>\"Não tenho resposta, mas estou com você.\"</td><td>\"Foi melhor assim\" ou \"foi vontade de Deus\".</td></tr><tr><td>\"Quer fazer a atividade agora ou depois?\"</td><td>\"A vida continua.\"</td></tr></tbody></table></div><h3>Quando morre um aluno ou um servidor</h3><ol class=\"passos\"><li>A direção confirma a informação com a família antes de falar.</li><li>A equipe é reunida e avisada primeiro.</li><li>Cada turma é avisada pelo próprio professor, em sala, com palavras simples e sem detalhes da morte.</li><li>A escola reserva um tempo para os alunos falarem, escreverem ou desenharem.</li><li>A rotina é retomada no mesmo dia, com flexibilidade.</li><li>A escola combina com a família como participar das despedidas.</li><li>Nas semanas seguintes, os professores observam os alunos mais próximos.</li></ol><div class=\"nota alerta\"><b>Em mortes violentas</b><br/>Não se comentam as circunstâncias, não se apontam culpados e não se compartilham imagens. Homenagens são simples e iguais para todos, sem exaltar a forma da morte.</div>"},{"id":"c19","titulo":"Quando o crime tenta atrair alunos","html":"<p>Em alguns territórios, grupos criminosos procuram adolescentes, e às vezes crianças, para tarefas como vigiar, transportar e vender. A aproximação raramente começa com ameaça. Começa com dinheiro, presentes, proteção e a sensação de pertencer a um grupo.</p><p>A lei trata esses adolescentes como vítimas de exploração. O uso de crianças e adolescentes no tráfico está na lista das piores formas de trabalho infantil (Decreto nº 6.481/2008).</p><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Fatores de risco</th><th>Fatores de proteção</th></tr></thead><tbody><tr><td>Faltas e abandono escolar.</td><td>Frequência e vínculo com a escola.</td></tr><tr><td>Sensação de não ter futuro pelo estudo.</td><td>Experiências de sucesso e projeto de vida.</td></tr><tr><td>Necessidade de renda na família.</td><td>Acesso a programas sociais e de aprendizagem profissional.</td></tr><tr><td>Familiares ou amigos envolvidos.</td><td>Um adulto de referência fora desse círculo.</td></tr><tr><td>Humilhação e exclusão na escola.</td><td>Respeito e pertencimento na turma.</td></tr><tr><td>Tempo livre sem supervisão.</td><td>Esporte, cultura e atividades no contraturno.</td></tr></tbody></table></div><h3>Sinais que pedem atenção</h3><ul><li>Dinheiro, roupas ou aparelhos sem explicação.</li><li>Novo grupo de amizades, mais velho, e afastamento dos colegas antigos.</li><li>Faltas que aumentam, sono em sala, saídas antes do fim da aula.</li><li>Gírias, gestos e símbolos ligados a grupos do território.</li><li>Mudança de postura: desafio aos adultos ou, ao contrário, medo e silêncio.</li><li>Comentários sobre dívidas, ameaças ou \"missões\".</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>A escola faz</th><th>A escola não faz</th></tr></thead><tbody><tr><td>Mantém o aluno na escola a todo custo.</td><td>Não expulsa, não transfere como punição e não rotula.</td></tr><tr><td>Conversa sobre futuro, sem sermão.</td><td>Não interroga sobre o envolvimento.</td></tr><tr><td>Leva à direção, que aciona a rede de proteção.</td><td>Não confronta pessoas do território.</td></tr><tr><td>Oferece atividades, responsabilidades e reconhecimento.</td><td>Não repassa nomes ou informações a ninguém fora da rede de proteção.</td></tr><tr><td>Trata com a família, com cuidado.</td><td>Não expõe a suspeita a colegas ou a outros responsáveis.</td></tr></tbody></table></div><div class=\"nota\"><b>Adolescentes ameaçados</b><br/>Quando há ameaça de morte contra um aluno, a direção comunica imediatamente ao Conselho Tutelar e à Secretaria. Existe um programa federal de proteção a crianças e adolescentes ameaçados de morte, acionado pelo Conselho Tutelar, pelo Ministério Público ou pela Justiça.</div>"},{"id":"c20","titulo":"Atendimento a responsáveis em situações tensas","html":"<p>A maioria dos conflitos com famílias se resolve com escuta. Alguns envolvem ameaça. A direção precisa de um modo de atender que proteja a equipe sem fechar a porta à família.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Medida</th><th>Como aplicar</th></tr></thead><tbody><tr><td>Local</td><td>Sala próxima à entrada, com porta que possa ficar aberta, e saída livre para o servidor.</td></tr><tr><td>Companhia</td><td>Atendimentos difíceis são feitos por duas pessoas.</td></tr><tr><td>Horário</td><td>Marcar horário, sempre que possível, em vez de atender na porta ou na sala de aula.</td></tr><tr><td>Registro</td><td>Anotar data, assunto e combinados. O responsável é informado do registro.</td></tr><tr><td>Professor</td><td>Responsável alterado não é levado à sala de aula. A direção atende primeiro.</td></tr><tr><td>Limite</td><td>Diante de gritos ou ofensas, encerrar com calma e remarcar.</td></tr><tr><td>Segurança</td><td>Diante de ameaça, proteger o servidor, registrar e comunicar à Secretaria. Em risco imediato, acionar o 190.</td></tr></tbody></table></div><div class=\"dialogo\"><div class=\"tt\">Roteiro de conversa · o responsável que chega alterado</div><div class=\"f\"><div class=\"q\">Direção</div><div class=\"b\">Bom dia. Vejo que o senhor está muito preocupado. Vamos conversar na minha sala.</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Eu quero falar com essa professora agora!</div></div><div class=\"f\"><div class=\"q\">Direção</div><div class=\"b\">Entendo. Primeiro quero ouvir o senhor, para resolver da melhor forma. O que aconteceu?</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Meu filho disse que ela gritou com ele na frente de todo mundo.</div></div><div class=\"f\"><div class=\"q\">Direção</div><div class=\"b\">Obrigada por me contar. Vou anotar, ouvir a professora e o seu filho, e dou um retorno ao senhor até amanhã. Pode ser?</div></div><div class=\"f o\"><div class=\"q\">Responsável</div><div class=\"b\">Se isso não se resolver, eu resolvo do meu jeito.</div></div><div class=\"f\"><div class=\"q\">Direção</div><div class=\"b\">Vou tratar com seriedade. Peço que o senhor também trate com a escola pelo diálogo. Ameaças eu sou obrigada a registrar. Amanhã, às dez horas, o senhor pode voltar?</div></div></div><h3>Depois do atendimento</h3><ul><li>Cumprir o prazo de retorno, mesmo que ainda não haja solução.</li><li>Ouvir o servidor citado em particular, sem prejulgar.</li><li>Ouvir o aluno com cuidado.</li><li>Registrar o desfecho.</li><li>Quando a queixa procede, reconhecer e dizer o que a escola fará.</li></ul><div class=\"nota\"><b>O que a lei prevê</b><br/>Ameaçar e desacatar servidor público no exercício da função são crimes previstos no Código Penal. A direção registra e comunica à Secretaria, que orienta as providências. O objetivo continua sendo proteger a equipe e manter o aluno na escola.</div>"},{"id":"c21","titulo":"Alunos em risco de abandonar a escola","html":"<p>Em territórios com violência, o abandono escolar raramente é uma decisão. É o resultado de medo no trajeto, mudança forçada de endereço, luto, trabalho ou envolvimento com grupos. Cada aluno que sai fica mais exposto.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Motivo</th><th>Sinais</th><th>O que a escola pode fazer</th></tr></thead><tbody><tr><td>Trajeto inseguro</td><td>Faltas em dias ou horários específicos.</td><td>Levar à Secretaria: rota do transporte, mudança de turno, vaga em escola mais próxima.</td></tr><tr><td>Não pode circular em certas áreas</td><td>Aluno ou família pede transferência sem explicar.</td><td>Atender com rapidez e discrição. Não exigir justificativa detalhada.</td></tr><tr><td>Família saiu às pressas</td><td>Aluno some. Vizinhos dizem que se mudaram.</td><td>Acionar a Secretaria e o Conselho Tutelar para localizar a nova matrícula.</td></tr><tr><td>Luto e medo</td><td>Faltas depois de uma morte ou de um episódio.</td><td>Visita ou contato de acolhimento. Flexibilizar prazos.</td></tr><tr><td>Trabalho</td><td>Cansaço, faltas, renda própria.</td><td>CRAS, programas sociais e aprendizagem profissional.</td></tr><tr><td>Envolvimento com grupos</td><td>Mudança de amizades, dinheiro, afastamento.</td><td>Manter o vínculo, acionar a rede de proteção, não rotular.</td></tr><tr><td>Gravidez e cuidado de irmãos</td><td>Faltas e atrasos.</td><td>Rede de saúde e assistência. Garantia legal de permanência.</td></tr></tbody></table></div><h3>Busca ativa em cinco passos</h3><ol class=\"passos\"><li>O professor avisa a secretaria da escola na terceira falta seguida.</li><li>A escola faz contato com os responsáveis no mesmo dia.</li><li>Sem contato, um servidor ou parceiro do território procura a família, com segurança.</li><li>A direção comunica ao Conselho Tutelar quando as faltas passam do limite legal ou quando há indício de violação de direitos.</li><li>A escola prepara a volta: acolhida, recuperação dos conteúdos e um adulto de referência.</li></ol><div class=\"nota alerta\"><b>Dever legal</b><br/>A Lei de Diretrizes e Bases determina que a escola notifique ao Conselho Tutelar a relação dos alunos com faltas acima de trinta por cento do percentual permitido em lei.</div>"},{"id":"c22","titulo":"Boatos, redes sociais e ameaças","html":"<p>Mensagens sobre tiroteios, toques de recolher e ameaças a escolas se espalham em minutos pelos grupos. Muitas são falsas, antigas ou de outra cidade. Mesmo assim, esvaziam a escola e geram pânico.</p><figure><div class=\"fluxo\"><div class=\"cx\"><span class=\"n\">1</span><b>Receber</b><small>não repassar</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">2</span><b>Verificar</b><small>com a direção e fontes oficiais</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">3</span><b>Comunicar</b><small>à Secretaria</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">4</span><b>Informar</b><small>famílias, por canal oficial</small></div><div class=\"seta\">&#8250;</div><div class=\"cx\"><span class=\"n\">5</span><b>Registrar</b><small>o que ocorreu</small></div></div><figcaption>Figura. O que fazer ao receber uma mensagem alarmante.</figcaption></figure><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Situação</th><th>Conduta</th></tr></thead><tbody><tr><td>Mensagem sobre confronto no bairro</td><td>A direção confirma com parceiros do território e com a Secretaria antes de qualquer decisão.</td></tr><tr><td>Boato de \"toque de recolher\"</td><td>A direção comunica à Secretaria, que orienta. A escola não divulga o boato.</td></tr><tr><td>Ameaça de ataque à escola em rede social</td><td>Guardar a imagem da mensagem, comunicar à direção e à Secretaria, que acionam a polícia. Não compartilhar.</td></tr><tr><td>Aluno que escreve ou desenha ameaças</td><td>Tratar com seriedade e sem pânico. Conversar em particular, comunicar à direção e chamar a família.</td></tr><tr><td>Responsáveis pedem informação</td><td>Responder apenas pelo canal oficial da escola, com o que foi confirmado.</td></tr><tr><td>Imprensa procura a escola</td><td>Encaminhar à Secretaria. Servidores não dão entrevistas sobre ocorrências.</td></tr></tbody></table></div><h3>Regras para os grupos de mensagens</h3><ul><li>A escola tem um canal oficial, e os responsáveis sabem qual é.</li><li>Servidores não repassam áudios, vídeos e mensagens não confirmados.</li><li>Nenhuma imagem de alunos, de vítimas ou de ocorrências é compartilhada.</li><li>Informações sobre o território não são comentadas em grupos.</li><li>Quem recebe algo preocupante envia só à direção.</li></ul><div class=\"nota alerta\"><b>Ameaças de ataque</b><br/>Toda ameaça é comunicada, mesmo que pareça brincadeira. Quem avalia a gravidade é a autoridade policial. A escola cuida de acolher, informar com calma e manter a rotina que for possível.</div>"},{"id":"c23","titulo":"Neutralidade e cuidado com as palavras","html":"<p>A escola atende filhos de todas as famílias do território, inclusive de pessoas envolvidas com o crime, de vítimas e de agentes de segurança. Para continuar sendo um lugar seguro para todos, ela não toma partido.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Princípio</th><th>Como se traduz no dia a dia</th></tr></thead><tbody><tr><td>Todos os alunos são alunos</td><td>Nenhum aluno é tratado de modo diferente pelo que a família faz ou pelo lugar onde mora.</td></tr><tr><td>A escola não comenta o território</td><td>Servidores não opinam sobre grupos, operações ou pessoas diante de alunos e responsáveis.</td></tr><tr><td>A escola não repassa informação</td><td>O que se sabe sobre alunos e famílias fica na escola e na rede de proteção.</td></tr><tr><td>A escola não aceita favores</td><td>Doações, festas e \"ajudas\" de origem duvidosa são recusadas com educação e comunicadas à Secretaria.</td></tr><tr><td>A escola não media disputas</td><td>Conflitos do território não são resolvidos dentro da escola.</td></tr></tbody></table></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Evitar dizer</th><th>Prefira</th></tr></thead><tbody><tr><td>\"Aqui só tem bandido.\"</td><td>\"Este bairro enfrenta muita violência.\"</td></tr><tr><td>\"Filho de traficante.\"</td><td>O nome do aluno.</td></tr><tr><td>\"Esse aí já está perdido.\"</td><td>\"Esse aluno precisa de mais apoio.\"</td></tr><tr><td>\"Você vai acabar como seu irmão.\"</td><td>\"Você pode escolher o seu caminho, e eu quero ajudar.\"</td></tr><tr><td>\"A polícia tem que acabar com eles.\"</td><td>Não comentar.</td></tr><tr><td>\"Lá na área de vocês...\"</td><td>\"No bairro...\"</td></tr></tbody></table></div><div class=\"nota\"><b>O que o aluno ouve</b><br/>Uma frase dita por um adulto da escola sobre o bairro ou sobre a família é levada para casa. Pode ferir o aluno e pode colocar o servidor em risco.</div>"},{"id":"c24","titulo":"Formar e cuidar da equipe","html":"<p>Um plano só funciona se as pessoas o conhecem e se sentem amparadas. Em escolas expostas à violência, o desgaste da equipe é alto e aparece em faltas, adoecimento e pedidos de remoção.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Quando</th><th>Ação de formação</th></tr></thead><tbody><tr><td>Início do ano</td><td>Apresentar o plano de segurança. Percorrer os locais mais seguros. Atualizar contatos.</td></tr><tr><td>Chegada de novo servidor</td><td>Orientação individual no primeiro dia: sinais, locais e a quem recorrer.</td></tr><tr><td>A cada semestre</td><td>Treino do procedimento com as turmas. Revisão do plano.</td></tr><tr><td>Depois de cada ocorrência</td><td>Reunião de avaliação: o que funcionou e o que mudar.</td></tr><tr><td>Ao longo do ano</td><td>Estudo dos guias de proteção do aluno e de sala de aula, família e território.</td></tr></tbody></table></div><h3>Cuidar de quem trabalha</h3><ul><li>Reunir a equipe no mesmo dia de uma ocorrência, para ouvir.</li><li>Permitir que cada um fale do que sentiu, sem obrigar.</li><li>Reconhecer o que a equipe fez bem.</li><li>Encaminhar ao serviço de saúde do servidor quem apresentar sofrimento persistente.</li><li>Distribuir as tarefas mais pesadas, para que não recaiam sempre nas mesmas pessoas.</li><li>Levar à Secretaria as necessidades de apoio psicológico e de segurança.</li></ul><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Sinais de desgaste na equipe</th><th>O que a direção pode fazer</th></tr></thead><tbody><tr><td>Irritação, choro, isolamento</td><td>Conversa individual e reservada.</td></tr><tr><td>Faltas e atrasos que aumentam</td><td>Perguntar do que a pessoa precisa antes de cobrar.</td></tr><tr><td>Medo de vir trabalhar</td><td>Levar à Secretaria. Rever trajeto e horário, se possível.</td></tr><tr><td>Indiferença: \"nada adianta\"</td><td>Mostrar resultados concretos. Dividir decisões.</td></tr></tbody></table></div><div class=\"nota\"><b>A direção também precisa de apoio</b><br/>Quem decide na crise carrega um peso grande. Mantenha contato com outros diretores, peça apoio à Secretaria e cuide da sua saúde.</div>"},{"id":"c25","titulo":"Registrar e aprender com cada ocorrência","html":"<p>O registro protege a escola, orienta a Secretaria e permite melhorar o plano. Ele descreve fatos e decisões, sem identificar pessoas do território.</p><div class=\"rapido\"><p><b>Escola:</b> ____________________ <b>Data:</b> ____/____/______ <b>Turno:</b> __________</p><p><b>O que ocorreu (fatos, horário de início e de fim):</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Nível de alerta adotado e quem decidiu:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Medidas tomadas:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Pessoas feridas ou que precisaram de atendimento:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Comunicações feitas (Secretaria, 190, 192, responsáveis) e horários:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>Aulas afetadas:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><p><b>O que funcionou e o que precisa mudar no plano:</b></p><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div><div style=\"border-bottom:0.2mm solid #B9C1CC;height:7mm\"></div></div><div class=\"tb\"><table class=\"larga\"><thead><tr><th>Indicador</th><th>Para que serve</th></tr></thead><tbody><tr><td>Dias e turnos com aulas interrompidas</td><td>Planejar a reposição e mostrar à rede o impacto.</td></tr><tr><td>Frequência nos dias seguintes a ocorrências</td><td>Identificar alunos que não voltaram.</td></tr><tr><td>Alunos em busca ativa e retornos</td><td>Acompanhar o risco de abandono.</td></tr><tr><td>Servidores afastados</td><td>Dimensionar o apoio à equipe.</td></tr><tr><td>Tempo para todos chegarem ao local mais seguro, nos treinos</td><td>Melhorar o procedimento.</td></tr></tbody></table></div><div class=\"nota\"><b>Registro reservado</b><br/>Os registros ficam com a direção e seguem para a Secretaria pelo canal oficial. Não são compartilhados em grupos de mensagens.</div>"},{"id":"c26","titulo":"Mais casos para estudo","html":"<div class=\"caso\"><div class=\"tt\">Exemplo de uso · o recado na porta</div><p><b>Situação.</b> No início da manhã, um homem diz ao porteiro que \"é melhor a escola não funcionar à tarde\".</p><p><b>O que fazer.</b></p><ol><li>O porteiro não discute e avisa a direção.</li><li>A direção comunica à Secretaria no mesmo momento.</li><li>A escola passa ao nível de atenção: sem atividades externas, portões controlados.</li><li>A Secretaria decide sobre o turno da tarde e a direção informa os responsáveis pelo canal oficial.</li><li>O contato é registrado, sem identificar a pessoa.</li></ol><p><b>Resultado esperado.</b> A decisão é tomada pela rede, e nenhum servidor fica exposto.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · os alunos que pararam de vir</div><p><b>Situação.</b> Depois de um confronto no bairro, onze alunos de uma mesma localidade faltam por uma semana.</p><p><b>O que fazer.</b></p><ol><li>A direção entende o motivo com parceiros do território, sem cobrar presença.</li><li>A escola faz contato de acolhimento com as famílias.</li><li>A Secretaria é informada e avalia o transporte e o trajeto.</li><li>Os professores preparam atividades para recuperar o que foi perdido.</li><li>Na volta, os alunos são recebidos sem perguntas diante da turma.</li></ol><p><b>Resultado esperado.</b> Os alunos retornam aos poucos, e a escola identifica dois que precisam de acompanhamento da rede.</p></div><div class=\"caso\"><div class=\"tt\">Exemplo de uso · a mãe que queria tirar o filho da turma</div><p><b>Situação.</b> Uma mãe exige a mudança de turma do filho porque ele estuda com o filho de uma família com quem ela tem conflito no bairro.</p><p><b>O que fazer.</b></p><ol><li>A direção ouve em particular e não comenta o conflito.</li><li>Avalia se há risco para os alunos dentro da escola.</li><li>Explica que a escola trata todos os alunos da mesma forma.</li><li>Se houver risco real, decide a medida com a Secretaria, com discrição e sem expor nenhuma das famílias.</li><li>Os professores observam a convivência entre os dois alunos.</li></ol><p><b>Resultado esperado.</b> A escola protege os dois alunos e não entra na disputa.</p></div>"},{"id":"c27","titulo":"Roteiro de estudo em grupo","html":"<p>Este guia rende mais quando é estudado com colegas. O roteiro abaixo divide a leitura em encontros de uma hora, que podem acontecer nas reuniões pedagógicas ou em grupos de estudo. Cada pessoa lê os capítulos antes do encontro.</p><div class=\"tb\"><table class=\"estreita\"><thead><tr><th>Encontro</th><th>Capítulos</th><th>Perguntas para a conversa</th></tr></thead><tbody><tr><td>1</td><td>Do início até \"A rede de proteção\"</td><td>Que conflitos com famílias são mais frequentes? Conhecemos os nossos parceiros na rede?</td></tr><tr><td>2</td><td>De \"Quando o território afeta a rotina\" até \"O plano de segurança\"</td><td>O nosso plano está escrito? Todos conhecem os locais mais seguros?</td></tr><tr><td>3</td><td>De \"Comunicação durante a crise\" até \"Relação com as forças de segurança\"</td><td>Quem fala com os responsáveis em uma ocorrência? Como tratamos pressões externas?</td></tr><tr><td>4</td><td>De \"Como a violência afeta a aprendizagem\" até \"Alunos em risco de abandonar\"</td><td>Como acolhemos alunos em luto? A nossa busca ativa funciona?</td></tr><tr><td>5</td><td>De \"Boatos\" até o final</td><td>Como cuidamos da equipe? O que vamos rever no plano?</td></tr></tbody></table></div><h3>Como conduzir cada encontro</h3><ol class=\"passos\"><li>Rodada inicial: cada um diz, em uma frase, o que mais chamou a atenção na leitura.</li><li>Discussão das perguntas, primeiro em duplas e depois no grupo.</li><li>Análise de um dos casos do guia ou de uma situação da escola, sem citar nomes.</li><li>Combinado: o que cada um vai experimentar até o próximo encontro.</li><li>No encontro seguinte, a conversa começa pelo relato do que foi experimentado.</li></ol><div class=\"nota\"><b>Registro</b><br/>As anotações sobre o território e sobre o plano de segurança são reservadas e ficam com a direção.</div>"},{"id":"c28","titulo":"Referências","html":"<ul><li>Estatuto da Criança e do Adolescente (Lei nº 8.069/1990), arts. 13, 56 e 245.</li><li>Lei nº 13.431/2017, sobre a escuta de crianças e adolescentes vítimas ou testemunhas de violência.</li><li>Lei nº 14.643/2023, que autoriza o Sistema Nacional de Acompanhamento e Combate à Violência nas Escolas.</li><li>Lei nº 13.935/2019, sobre serviços de psicologia e de serviço social nas redes públicas de educação básica.</li><li>Comitê Internacional da Cruz Vermelha: metodologia Acesso Mais Seguro para Serviços Públicos Essenciais e guia de Comportamentos Mais Seguros para profissionais da educação.</li><li>Ministério da Educação: programa Escola que Protege.</li></ul>"},{"id":"c29","titulo":"Verifique o que aprendeu","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> Durante disparos no entorno, a direção deve:</p><ol type=\"a\"><li>Liberar os alunos rapidamente.</li><li>Manter os alunos na escola, em local mais seguro.</li><li>Mandar olhar pela janela para avaliar.</li><li>Ligar para os responsáveis virem buscar.</li></ol></div><div class=\"qz\"><p><b>2.</b> Um grupo armado pede que a escola feche mais cedo. A direção deve:</p><ol type=\"a\"><li>Negociar um horário.</li><li>Recusar e enfrentar.</li><li>Comunicar imediatamente à Secretaria, sem negociar sozinha.</li><li>Avisar os alunos em sala.</li></ol></div><div class=\"qz\"><p><b>3.</b> Diante da suspeita de maus-tratos contra um aluno, a escola:</p><ol type=\"a\"><li>Investiga até ter certeza.</li><li>Comunica ao Conselho Tutelar.</li><li>Aguarda a família procurar.</li><li>Conversa com o suposto agressor.</li></ol></div><div class=\"qz\"><p><b>4.</b> Não se faz mediação quando:</p><ol type=\"a\"><li>Há uma discussão entre colegas.</li><li>Uma das partes tem medo da outra ou houve violência grave.</li><li>Os dois alunos aceitam conversar.</li><li>O conflito é antigo.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> b) Manter os alunos na escola, em local mais seguro. Enquanto há risco, a escola é mais segura do que a rua.</p><p><b>2.</b> c) Comunicar imediatamente à Secretaria, sem negociar sozinha. A escola não negocia nem confronta.</p><p><b>3.</b> b) Comunica ao Conselho Tutelar. A comunicação da suspeita é obrigatória.</p><p><b>4.</b> b) Uma das partes tem medo da outra ou houve violência grave. Nesses casos, a escola protege a vítima.</p></div>"},{"id":"c30","titulo":"Glossário","html":"<dl><dt>Aliciamento</dt><dd>Aproximação gradual de um adulto ou de um grupo para explorar uma criança ou um adolescente.</dd><dt>Busca ativa</dt><dd>Ação da escola e da rede para localizar e trazer de volta o aluno que deixou de frequentar.</dd><dt>CAPS</dt><dd>Centro de Atenção Psicossocial. Atende sofrimento psíquico intenso e uso de substâncias.</dd><dt>Comportamento mais seguro</dt><dd>Conjunto de condutas que reduzem o risco durante situações de violência armada.</dd><dt>Conselho Tutelar</dt><dd>Órgão que zela pelos direitos de crianças e adolescentes.</dd><dt>CRAS</dt><dd>Centro de Referência de Assistência Social. Atende famílias em vulnerabilidade.</dd><dt>CREAS</dt><dd>Centro de Referência Especializado de Assistência Social. Atende situações de violação de direitos.</dd><dt>Estado de alerta</dt><dd>Condição em que o corpo se mantém preparado para o perigo, o que prejudica a atenção e a memória.</dd><dt>Local mais seguro</dt><dd>Espaço da escola mais protegido de disparos, definido no plano de segurança.</dd><dt>Neutralidade</dt><dd>Princípio pelo qual a escola atende a todos e não toma partido em disputas do território.</dd><dt>Nível de alerta</dt><dd>Grau de risco definido pela direção, com ações combinadas para cada um.</dd><dt>Plano de segurança</dt><dd>Documento que define responsáveis, sinais, locais e procedimentos da escola em situações de risco.</dd><dt>Rede de proteção</dt><dd>Conjunto de serviços que garantem os direitos de crianças e adolescentes.</dd><dt>Território</dt><dd>O bairro e o entorno onde a escola está, com as suas relações e os seus riscos.</dd></dl>"},{"id":"c31","titulo":"Avaliação final","html":"<div class=\"quiz\"><div class=\"qz\"><p><b>1.</b> O mapa do território da escola deve ser:</p><ol type=\"a\"><li>Afixado no mural.</li><li>Reservado à direção, sem nomes de pessoas.</li><li>Enviado ao grupo dos responsáveis.</li><li>Dispensável.</li></ol></div><div class=\"qz\"><p><b>2.</b> No nível de alerta, com ocorrência no entorno, os alunos:</p><ol type=\"a\"><li>São liberados para casa.</li><li>Permanecem dentro dos prédios, longe de áreas expostas.</li><li>Vão para o pátio.</li><li>Aguardam no portão.</li></ol></div><div class=\"qz\"><p><b>3.</b> Um recado para fechar a escola deve ser:</p><ol type=\"a\"><li>Atendido de imediato.</li><li>Comunicado à Secretaria, que decide.</li><li>Discutido com o portador.</li><li>Ignorado.</li></ol></div><div class=\"qz\"><p><b>4.</b> Durante uma ocorrência, a mensagem aos responsáveis diz que:</p><ol type=\"a\"><li>Venham buscar os alunos.</li><li>Os alunos estão protegidos e que não venham agora.</li><li>A escola não sabe o que fazer.</li><li>Há detalhes do confronto.</li></ol></div><div class=\"qz\"><p><b>5.</b> Diante de um aluno aliciado por grupo criminoso, a escola:</p><ol type=\"a\"><li>Expulsa.</li><li>Mantém o vínculo e aciona a rede de proteção.</li><li>Investiga.</li><li>Avisa os colegas.</li></ol></div><div class=\"qz\"><p><b>6.</b> Uma arma encontrada na escola deve ser:</p><ol type=\"a\"><li>Guardada na direção.</li><li>Isolada, sem toque, com acionamento do 190.</li><li>Fotografada para os grupos.</li><li>Entregue ao aluno.</li></ol></div><div class=\"qz\"><p><b>7.</b> Pedido de dados de alunos por autoridade deve ser:</p><ol type=\"a\"><li>Atendido verbalmente.</li><li>Solicitado por escrito e encaminhado à Secretaria.</li><li>Negado sempre.</li><li>Publicado.</li></ol></div><div class=\"qz\"><p><b>8.</b> Depois de uma ocorrência, a direção deve:</p><ol type=\"a\"><li>Evitar o assunto.</li><li>Reunir a equipe, acolher, registrar e rever o plano.</li><li>Punir quem errou.</li><li>Fechar a escola por uma semana.</li></ol></div></div><div class=\"gab\"><b>Respostas</b><p><b>1.</b> b) Reservado à direção, sem nomes de pessoas. É informação sensível.</p><p><b>2.</b> b) Permanecem dentro dos prédios, longe de áreas expostas. A escola é mais segura do que a rua.</p><p><b>3.</b> b) Comunicado à Secretaria, que decide. Nenhum gestor decide ou negocia sozinho.</p><p><b>4.</b> b) Os alunos estão protegidos e que não venham agora. Mensagem curta e verdadeira.</p><p><b>5.</b> b) Mantém o vínculo e aciona a rede de proteção. O adolescente é vítima de exploração.</p><p><b>6.</b> b) Isolada, sem toque, com acionamento do 190. Ninguém manuseia.</p><p><b>7.</b> b) Solicitado por escrito e encaminhado à Secretaria. Dados são protegidos por lei.</p><p><b>8.</b> b) Reunir a equipe, acolher, registrar e rever o plano. Cada ocorrência melhora o plano.</p></div>"}];
